// LC 200：四连通的 '1' 算一块。发现未访问陆地就计数，并把它整块沉掉。
// 换题：八连通就在 dfsIsland 里再递归四个对角。
// 统计面积时 dfs 改返回 int：出界或不是 '1' 返回 0，否则标记后 return 1 + 四个方向。
// 不能改原网格时，用 boolean[][] vis，进入前 vis[r][c] = true，判断条件改成 vis[r][c]。
static int numIslands(char[][] grid) {
    if (grid == null || grid.length == 0 || grid[0].length == 0) return 0;
    int m = grid.length, n = grid[0].length, cnt = 0;
    for (int i = 0;
    i < m;
    i++) {
        for (int j = 0;
        j < n;
        j++) {
            if (grid[i][j] == '1') {
                cnt++;
                dfsIsland(grid, i, j);
            }
        }
    }
    return cnt;
}
static void dfsIsland(char[][] grid, int r, int c) {
    int m = grid.length, n = grid[0].length;
    if (r < 0 || c < 0 || r >= m || c >= n || grid[r][c] != '1') return;
    grid[r][c] = '0';
    // 发现即标记，防止重复进同一格
    dfsIsland(grid, r + 1, c);
    dfsIsland(grid, r - 1, c);
    dfsIsland(grid, r, c + 1);
    dfsIsland(grid, r, c - 1);
}

// LC 994：值为 2 的橘子一起当第 0 层。一分钟内当前层同时感染四邻的 1。
// 入队时就把格子改成 2，保证每个新鲜橘子只进队一次。
// 换单源最短路：队列只放起点，第一次扩展到终点就返回该层步数，队列空返回 -1。
// 换八方向：dirs 加上 {-1,-1},{-1,1},{1,-1},{1,1}。
// 换 934：源是第一座岛的全部格子，碰到另一座岛的 1 时返回 步数-1（踩上对岸的那一步不是翻 0）。
static int orangesRotting(int[][] grid) {
    int m = grid.length, n = grid[0].length;
    ArrayDeque<int[]> q = new ArrayDeque<>();
    int fresh = 0;
    for (int i = 0;
    i < m;
    i++) {
        for (int j = 0;
        j < n;
        j++) {
            if (grid[i][j] == 2) q.offer(new int[]{
                i, j
            }
            );
            else if (grid[i][j] == 1) fresh++;
        }
    }
    if (fresh == 0) return 0;
    int[][] dirs = {
    {
        1, 0
    }
    , {
    -1, 0
    }
    , {
    0, 1
    }
    , {
    0, -1
    }
    }
    ;
    int minutes = 0;
    while (!q.isEmpty() && fresh > 0) {
        int sz = q.size();
        // 本层结束才算过了一分钟
        for (int k = 0;
        k < sz;
        k++) {
            int[] cur = q.poll();
            for (int[] d : dirs) {
                int nr = cur[0] + d[0], nc = cur[1] + d[1];
                if (nr < 0 || nc < 0 || nr >= m || nc >= n || grid[nr][nc] != 1) continue;
                grid[nr][nc] = 2;
                fresh--;
                q.offer(new int[]{
                    nr, nc
                }
                );
            }
        }
        minutes++;
    }
    return fresh == 0 ? minutes : -1;
}

