// LC 207：prerequisites[i] = [a, b] 表示先学 b 再学 a，有向边 b -> a，a 的入度 +1。
// 换题要一种合法顺序（LC 210）：出队时把 u 依次写入 List；seen < numCourses 说明有环，返回空列表。
// 换题判断拓扑序是否唯一：每一轮开始时，队列里入度为 0 的点必须恰好 1 个。
static boolean canFinish(int numCourses, int[][] prerequisites) {
    List<List<Integer>> g = new ArrayList<>();
    for (int i = 0;
    i < numCourses;
    i++) g.add(new ArrayList<>());
    int[] indeg = new int[numCourses];
    for (int[] e : prerequisites) {
        g.get(e[1]).add(e[0]);
        indeg[e[0]]++;
    }
    ArrayDeque<Integer> q = new ArrayDeque<>();
    for (int i = 0;
    i < numCourses;
    i++) {
        if (indeg[i] == 0) q.offer(i);
    }
    int seen = 0;
    while (!q.isEmpty()) {
        int u = q.poll();
        seen++;
        for (int v : g.get(u)) {
            if (--indeg[v] == 0) q.offer(v);
        }
    }
    return seen == numCourses;
}

// 路径压缩 + 按大小合并。comp 初始为点数，每成功合并一次减 1。
static class UnionFind {
    int[] parent, size;
    int comp;
    UnionFind(int n) {
        parent = new int[n];
        size = new int[n];
        comp = n;
        for (int i = 0;
        i < n;
        i++) {
            parent[i] = i;
            size[i] = 1;
        }
    }
    int find(int x) {
        if (parent[x] != x) parent[x] = find(parent[x]);
        return parent[x];
    }
    boolean union(int a, int b) {
        int ra = find(a), rb = find(b);
        if (ra == rb) return false;
        if (size[ra] < size[rb]) {
            int t = ra;
            ra = rb;
            rb = t;
        }
        parent[rb] = ra;
        size[ra] += size[rb];
        comp--;
        return true;
    }
}
// LC 547：isConnected[i][j] == 1 是无向边。返回省的个数。
// 换 684 冗余连接：按 edges 顺序 union，第一次返回 false 的那条边就是答案，不要返回 comp。
// 换 200：只给陆地编号 i * n + j，与右边、下边的陆地 union；水也占了初始编号，岛屿数是陆地上不同根的个数，不能直接用 comp。
static int findCircleNum(int[][] isConnected) {
    int n = isConnected.length;
    UnionFind uf = new UnionFind(n);
    for (int i = 0;
    i < n;
    i++) {
        for (int j = i + 1;
        j < n;
        j++) {
            if (isConnected[i][j] == 1) uf.union(i, j);
        }
    }
    return uf.comp;
}

